<?php
require __DIR__ . '/config/koneksi.php'; $today=date('Y-m-d'); $notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['id']??0); $status=$_POST['status']??'';
 if($id>0 && in_array($status,['Menunggu','Diproses','Selesai','Dibatalkan'],true)){$q=$pdo->prepare('UPDATE antrean SET status=? WHERE id=? AND tanggal=?');$q->execute([$status,$id,$today]);$notice='Status pesanan berhasil diperbarui.';}
}
$q=$pdo->prepare('SELECT * FROM antrean WHERE tanggal=? ORDER BY nomor_antrean ASC');$q->execute([$today]);$rows=$q->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Antrean</title><link rel="stylesheet" href="style.css"></head><body><header class="header"><div class="brand"><div class="brand-mark">K</div><div><b>PANEL PETUGAS</b><small>Pengelolaan pesanan kantin</small></div></div><nav><a href="index.php">← Halaman Antrean</a></nav></header><main class="wrap staff-wrap"><div class="staff-title"><span class="kicker">PENGELOLAAN PESANAN</span><h1>Daftar antrean masuk</h1><p>Perbarui status pesanan sesuai proses di kantin.</p></div><?php if($notice):?><div class="success"><?=h($notice)?></div><?php endif;?><section class="panel"><div class="staff-table"><div class="staff-head"><span>NO.</span><span>PEMESAN & PESANAN</span><span>CATATAN</span><span>STATUS / AKSI</span></div><?php if(!$rows):?><div class="empty">Belum ada pesanan hari ini.</div><?php else:foreach($rows as $r):?><div class="staff-row"><b><?=h(nomorAntrean($r['nomor_antrean']))?></b><div><strong><?=h($r['nama_pemesan'])?></strong><small><?=h($r['nama_produk'])?> × <?= (int)$r['jumlah']?></small></div><span><?=h($r['catatan']?:'-')?></span><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?= $r['status']==='Menunggu'?'selected':''?>>Menunggu</option><option <?= $r['status']==='Diproses'?'selected':''?>>Diproses</option><option <?= $r['status']==='Selesai'?'selected':''?>>Selesai</option><option <?= $r['status']==='Dibatalkan'?'selected':''?>>Dibatalkan</option></select><button class="small-btn">Simpan</button></form></div><?php endforeach;endif;?></div></section><p class="refresh-note">Panel ini tidak menggunakan login admin.</p></main></body></html>
